//! Python type stub (`.pyi`) generation.

use std::fmt::Write;

use crate::schema::{Schema, Ty};

const HEADER: &str = "\
# This file was generated by heracless. Do not edit it by hand:
# it is rewritten whenever the config is loaded with stub generation enabled.
";

/// Names used in annotations that a field of the same name would shadow inside
/// its class body (`datetime: datetime.datetime` breaks the annotations after it).
const SHADOWABLE: &[&str] = &["bool", "datetime", "float", "int", "str", "tuple", "typing"];

/// How annotations are spelled inside one class body.
#[derive(Default)]
struct Scope {
    /// Shadowable names that are fields of the class being rendered.
    shadowed: Vec<&'static str>,
    /// Modules the rendered annotations need: (module, alias).
    imports: std::collections::BTreeSet<(&'static str, &'static str)>,
}

impl Scope {
    fn for_class(schema: &Schema, id: usize) -> Scope {
        let fields = &schema.class(id).fields;
        Scope {
            shadowed: SHADOWABLE
                .iter()
                .copied()
                .filter(|name| fields.iter().any(|f| f.name == *name))
                .collect(),
            imports: Default::default(),
        }
    }

    /// `name` from `module`, through a private alias if `module` (or `name`, for
    /// builtins) is shadowed. Aliases like `_typing_` can't collide with field
    /// names: those never both start and end with an underscore.
    fn qualified(&mut self, module: &'static str, alias: &'static str, name: &str) -> String {
        let shadowed = self
            .shadowed
            .contains(&if module == "builtins" { name } else { module });
        match (module, shadowed) {
            ("builtins", false) => name.to_string(),
            (_, false) => {
                self.imports.insert((module, module));
                format!("{module}.{name}")
            }
            (_, true) => {
                self.imports.insert((module, alias));
                format!("{alias}.{name}")
            }
        }
    }

    fn render(&mut self, schema: &Schema, ty: &Ty) -> String {
        match ty {
            Ty::Any => self.qualified("typing", "_typing_", "Any"),
            Ty::None => "None".into(),
            Ty::Bool => self.qualified("builtins", "_builtins_", "bool"),
            Ty::Int => self.qualified("builtins", "_builtins_", "int"),
            Ty::Float => self.qualified("builtins", "_builtins_", "float"),
            Ty::Str => self.qualified("builtins", "_builtins_", "str"),
            Ty::Date => self.qualified("datetime", "_datetime_", "date"),
            Ty::DateTime => self.qualified("datetime", "_datetime_", "datetime"),
            Ty::List(element) => {
                let tuple = self.qualified("builtins", "_builtins_", "tuple");
                format!("{tuple}[{}, ...]", self.render(schema, element))
            }
            Ty::Class(id) => schema.class(*id).name.clone(),
            Ty::Union(members) => {
                // `None` goes last: `int | None` reads better than `None | int`.
                let (none, rest): (Vec<&Ty>, Vec<&Ty>) =
                    members.iter().partition(|m| **m == Ty::None);
                rest.into_iter()
                    .chain(none)
                    .map(|m| self.render(schema, m))
                    .collect::<Vec<_>>()
                    .join(" | ")
            }
        }
    }
}

/// Render a type as a Python annotation (`int`, `tuple[str, ...]`, `Server | None`).
pub fn render_type(schema: &Schema, ty: &Ty) -> String {
    Scope::default().render(schema, ty)
}

/// Generate a `.pyi` stub declaring one dataclass per config class plus a
/// `load_config` signature returning the root `Config`.
pub fn generate_stub(schema: &Schema, frozen: bool) -> String {
    let decorator = if frozen {
        "@dataclass(frozen=True)"
    } else {
        "@dataclass"
    };
    let mut imports = std::collections::BTreeSet::from([("pathlib", "pathlib")]);
    let mut body = String::new();

    for id in schema.ordered() {
        let class = schema.class(id);
        let mut scope = Scope::for_class(schema, id);
        let _ = write!(body, "\n\n{decorator}\nclass {}:\n", class.name);
        if class.fields.is_empty() {
            body.push_str("    ...\n");
        }
        for field in &class.fields {
            let _ = writeln!(
                body,
                "    {}: {}",
                field.name,
                scope.render(schema, &field.ty)
            );
        }
        imports.append(&mut scope.imports);
    }

    let mut out = String::from(HEADER);
    for (module, alias) in imports {
        if module == alias {
            let _ = writeln!(out, "import {module}");
        } else {
            let _ = writeln!(out, "import {module} as {alias}");
        }
    }
    out.push_str("from dataclasses import dataclass\n");
    out.push_str(&body);
    out.push_str(
        "\n\ndef load_config(\n    config_path: pathlib.Path | str | None = ...,\n    frozen: bool = ...,\n    stub_dump: bool = ...,\n) -> Config: ...\n",
    );
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::value::Value;
    use crate::yaml::parse_str;
    use pretty_assertions::assert_eq;

    fn stub(src: &str, frozen: bool) -> String {
        let Value::Map(map) = parse_str(src).unwrap() else {
            panic!()
        };
        generate_stub(&Schema::infer(&map), frozen)
    }

    #[test]
    fn full_stub() {
        let src = "\
name: app
when: 2001-01-23
ports: [80, 443]
db:
  host: localhost
  replicas:
    - {host: a, weight: 1}
    - {host: b}
empty: {}
";
        let expected = format!(
            "{HEADER}import datetime
import pathlib
from dataclasses import dataclass


@dataclass(frozen=True)
class Config:
    name: str
    when: datetime.date
    ports: tuple[int, ...]
    db: Db
    empty: Empty


@dataclass(frozen=True)
class Db:
    host: str
    replicas: tuple[ReplicasItem, ...]


@dataclass(frozen=True)
class ReplicasItem:
    host: str
    weight: int | None


@dataclass(frozen=True)
class Empty:
    ...


def load_config(
    config_path: pathlib.Path | str | None = ...,
    frozen: bool = ...,
    stub_dump: bool = ...,
) -> Config: ...
"
        );
        assert_eq!(stub(src, true), expected);
    }

    #[test]
    fn shadowing_fields_use_private_aliases() {
        let out = stub(
            "typing: x\nint: 1\nitems: []\nd: 2020-01-01\nother: {n: 1, items: []}\n",
            true,
        );
        assert!(out.contains("import builtins as _builtins_\nimport datetime\nimport pathlib\nimport typing as _typing_\nimport typing\n"));
        assert!(out.contains("    typing: str\n    int: _builtins_.int\n    items: tuple[_typing_.Any, ...]\n    d: datetime.date\n"));
        // Classes without shadowing fields keep the plain spelling.
        assert!(out.contains("class Other:\n    n: int\n    items: tuple[typing.Any, ...]\n"));
    }

    #[test]
    fn mutable_and_any() {
        let out = stub("a: []\n", false);
        assert!(out.contains("import typing\n"));
        assert!(out.contains("@dataclass\nclass Config:\n    a: tuple[typing.Any, ...]\n"));
    }
}
